import{_ as l,a0 as t,w as r,s as o,ao as d,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上壓縮文件的 5 種方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上壓縮文件的 5 種方法 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上壓縮文件的 5 種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上壓縮文件的 5 種方法 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200417 How to compress files on Linux 5 ways","title":"在 Linux 上壓縮文件的 5 種方法","tag":"202005","desc":""},"relativePath":"202005/20200417 How to compress files on Linux 5 ways.md","filePath":"[post].md"}'),c={name:"202005/20200417 How to compress files on Linux 5 ways.md"};function h(g,s,b,f,k,u){const n=t("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="在-linux-上壓縮文件的-5-種方法" tabindex="-1">在 Linux 上壓縮文件的 5 種方法 <a class="header-anchor" href="#在-linux-上壓縮文件的-5-種方法" aria-label="Permalink to “在 Linux 上壓縮文件的 5 種方法”">​</a></h1><blockquote><p>在 Linux 系統上有很多可以用於壓縮文件的工具，但它們的表現並不都是一樣的，也不是所有的壓縮效果都是一樣的。在這篇文章中，我們比較其中的五個工具。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/06/231536tgxma941yb8dgl53.jpg" alt=""></p><p>在 Linux 上有不少用於壓縮文件的命令。最新最有效的一個方法是 <code>xz</code>，但是所有的方法都有節省磁盤空間和維護備份文件供以後使用的優點。在這篇文章中，我們將比較這些壓縮命令並指出顯著的不同。</p><h3 id="tar" tabindex="-1">tar <a class="header-anchor" href="#tar" aria-label="Permalink to “tar”">​</a></h3><p><code>tar</code> 命令不是專門的壓縮命令。它通常用於將多個文件拉入一個單個的文件中，以便容易地傳輸到另一個系統，或者將文件作為一個相關的組進行備份。它也提供壓縮的功能，這就很有意義了，附加一個 <code>z</code> 壓縮選項能夠實現壓縮文件。</p><p>當使用 <code>z</code> 選項為 <code>tar</code> 命令附加壓縮過程時，<code>tar</code> 使用 <code>gzip</code> 來進行壓縮。</p><p>就像壓縮一組文件一樣，你可以使用 <code>tar</code> 來壓縮單個文件，儘管這種操作與直接使用 <code>gzip</code> 相比沒有特別的優勢。要使用 <code>tar</code> 這樣做，只需要使用 <code>tar cfz newtarfile filename</code> 命令來標識要壓縮的文件，就像標識一組文件一樣，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar cfz bigfile.tgz bigfile</span></span>
<span class="line"><span>            ^            ^</span></span>
<span class="line"><span>            |            |</span></span>
<span class="line"><span>            +- 新的文件  +- 將被壓縮的文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 103270400 Apr 16 16:09 bigfile</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21608325 Apr 16 16:08 bigfile.tgz</span></span></code></pre></div><p>注意，文件的大小顯著減少了。</p><p>如果你願意，你可以使用 <code>tar.gz</code> 擴展名，這可能會使文件的特徵更加明顯，但是大多數的 Linux 用户將很可能會意識到與 <code>tgz</code> 的意思是一樣的 – <code>tar</code> 和 <code>gz</code> 的組合來顯示文件是一個壓縮的 tar 文件。在壓縮完成後，你將同時得到原始文件和壓縮文件。</p><p>要將很多文件收集在一起並在一個命令中壓縮出 “tar ball”，使用相同的語法，但要指定要包含的文件為一組，而不是單個文件。這裏有一個示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar cfz bin.tgz bin/*</span></span>
<span class="line"><span>          ^         ^</span></span>
<span class="line"><span>          |         +-- 將被包含的文件</span></span>
<span class="line"><span>          + 新的文件</span></span></code></pre></div><h3 id="zip" tabindex="-1">zip <a class="header-anchor" href="#zip" aria-label="Permalink to “zip”">​</a></h3><p><code>zip</code> 命令創建一個壓縮文件，與此同時保留原始文件的完整性。語法像使用 <code>tar</code> 一樣簡單，只是你必需記住，你的原始文件名稱應該是命令列上的最後一個參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zip ./bigfile.zip bigfile</span></span>
<span class="line"><span>updating: bigfile (deflated 79%)</span></span>
<span class="line"><span>$ ls -l bigfile bigfile.zip</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 103270400 Apr 16 11:18 bigfile</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs  21606889 Apr 16 11:19 bigfile.zip</span></span></code></pre></div><h3 id="gzip" tabindex="-1">gzip <a class="header-anchor" href="#gzip" aria-label="Permalink to “gzip”">​</a></h3><p><code>gzip</code> 命令非常容易使用。你只需要鍵入 <code>gzip</code>，緊隨其後的是你想要壓縮的文件名稱。不像上述描述的命令，<code>gzip</code> 將“就地”“加密”文件。換句話説，原始文件將被“加密”文件替換。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip bigfile</span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs  21606751 Apr 15 17:57 bigfile.gz</span></span></code></pre></div><h3 id="bzip2" tabindex="-1">bzip2 <a class="header-anchor" href="#bzip2" aria-label="Permalink to “bzip2”">​</a></h3><p>像使用 <code>gzip</code> 命令一樣，<code>bzip2</code> 將在你選擇的文件“就地”壓縮，不留下原始文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bzip bigfile</span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs  18115234 Apr 15 17:57 bigfile.bz2</span></span></code></pre></div><h3 id="xz" tabindex="-1">xz <a class="header-anchor" href="#xz" aria-label="Permalink to “xz”">​</a></h3><p><code>xz</code> 是壓縮命令團隊中的一個相對較新的成員，在壓縮文件的能力方面，它是一個領跑者。像先前的兩個命令一樣，你只需要將文件名稱提供給命令。再強調一次，原始文件被就地壓縮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xz bigfile</span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 13427236 Apr 15 17:30 bigfile.xz</span></span></code></pre></div><p>對於大文件來説，你可能會注意到 <code>xz</code> 將比其它的壓縮命令花費更多的運行時間，但是壓縮的結果卻是非常令人讚歎的。</p><h3 id="對比" tabindex="-1">對比 <a class="header-anchor" href="#對比" aria-label="Permalink to “對比”">​</a></h3><p>大多數人都聽説過“大小不是一切”。所以，讓我們比較一下文件大小以及一些當你計劃如何壓縮文件時的問題。</p><p>下面顯示的統計數據都與壓縮單個文件相關，在上面顯示的示例中使用 <code>bigfile</code>。這個文件是一個大的且相當隨機的文本文件。壓縮率在一定程度上取決於文件的內容。</p><h4 id="大小減縮率" tabindex="-1">大小減縮率 <a class="header-anchor" href="#大小減縮率" aria-label="Permalink to “大小減縮率”">​</a></h4><p>當比較時，上面顯示的各種壓縮命產生下面的結果。百分比表示壓縮文件與原始文件的比較效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r-- 1 shs shs 103270400 Apr 16 14:01 bigfile</span></span>
<span class="line"><span>------------------------------------------------------</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 18115234 Apr 16 13:59 bigfile.bz2    ~17%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21606751 Apr 16 14:00 bigfile.gz     ~21%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21608322 Apr 16 13:59 bigfile.tgz    ~21%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 13427236 Apr 16 14:00 bigfile.xz     ~13%</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 21606889 Apr 16 13:59 bigfile.zip    ~21%</span></span></code></pre></div><p><code>xz</code> 命令獲勝，最終只有壓縮文件 13% 的大小，但是所有這些壓縮命令都相當顯著地減少原始文件的大小。</p><h4 id="是否替換原始文件" tabindex="-1">是否替換原始文件 <a class="header-anchor" href="#是否替換原始文件" aria-label="Permalink to “是否替換原始文件”">​</a></h4><p><code>bzip2</code>、<code>gzip</code> 和 <code>xz</code> 命令都用壓縮文件替換原始文件。<code>tar</code> 和 <code>zip</code> 命令不替換。</p><h4 id="運行時間" tabindex="-1">運行時間 <a class="header-anchor" href="#運行時間" aria-label="Permalink to “運行時間”">​</a></h4><p><code>xz</code> 命令似乎比其它命令需要花費更多的時間來“加密”文件。對於 <code>bigfile</code> 來説，大概的時間是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令      運行時間</span></span>
<span class="line"><span>tar       4.9 秒</span></span>
<span class="line"><span>zip       5.2 秒</span></span>
<span class="line"><span>bzip2    22.8 秒</span></span>
<span class="line"><span>gzip      4.8 秒</span></span>
<span class="line"><span>xz       50.4 秒</span></span></code></pre></div><p>解壓縮文件很可能比壓縮時間要短得多。</p><h4 id="文件權限" tabindex="-1">文件權限 <a class="header-anchor" href="#文件權限" aria-label="Permalink to “文件權限”">​</a></h4><p>不管你對壓縮文件設置什麼權限，壓縮文件的權限將基於你的 <code>umask</code> 設置，但 <code>bzip2</code> 除外，它保留了原始文件的權限。</p><h4 id="與-windows-的兼容性" tabindex="-1">與 Windows 的兼容性 <a class="header-anchor" href="#與-windows-的兼容性" aria-label="Permalink to “與 Windows 的兼容性”">​</a></h4><p><code>zip</code> 命令創建的文件可以在 Windows 系統以及 Linux 和其他 Unix 系統上使用（即解壓），而無需安裝其他工具，無論這些工具可能是可用還是不可用的。</p><h3 id="解壓縮文件" tabindex="-1">解壓縮文件 <a class="header-anchor" href="#解壓縮文件" aria-label="Permalink to “解壓縮文件”">​</a></h3><p>解壓文件的命令與壓縮文件的命令類似。在我們運行上述壓縮命令後，這些命令用於解壓縮 <code>bigfile</code>：</p><ul><li>tar： <code>tar xf bigfile.tgz</code></li><li>zip： <code>unzip bigfile.zip</code></li><li>gzip： <code>gunzip bigfile.gz</code></li><li>bzip2： <code>bunzip2 bigfile.gz2</code></li><li>xz： <code>xz -d bigfile.xz</code> 或 <code>unxz bigfile.xz</code></li></ul><h3 id="自己運行壓縮對比" tabindex="-1">自己運行壓縮對比 <a class="header-anchor" href="#自己運行壓縮對比" aria-label="Permalink to “自己運行壓縮對比”">​</a></h3><p>如果你想自己運行一些測試，抓取一個大的且可以替換的文件，並使用上面顯示的每個命令來壓縮它 —— 最好使用一個新的子目錄。你可能需要先安裝 <code>xz</code>，如果你想在測試中包含它的話。這個腳本可能更容易地進行壓縮，但是可能需要花費幾分鐘完成。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 詢問用户文件名稱</span></span>
<span class="line"><span>echo -n &quot;filename&gt; &quot;</span></span>
<span class="line"><span>read filename</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 你需要這個，因為一些命令將替換原始文件</span></span>
<span class="line"><span>cp $filename $filename-2</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 先清理(以免先前的結果仍然可用)</span></span>
<span class="line"><span>rm $filename.*</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tar cvfz ./$filename.tgz $filename &gt; /dev/null</span></span>
<span class="line"><span>zip $filename.zip $filename &gt; /dev/null</span></span>
<span class="line"><span>bzip2 $filename</span></span>
<span class="line"><span># 恢復原始文件</span></span>
<span class="line"><span>cp $filename-2 $filename</span></span>
<span class="line"><span>gzip $filename</span></span>
<span class="line"><span># 恢復原始文件</span></span>
<span class="line"><span>cp $filename-2 $filename</span></span>
<span class="line"><span>xz $filename</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 顯示結果</span></span>
<span class="line"><span>ls -l $filename.*</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 替換原始文件</span></span>
<span class="line"><span>mv $filename-2 $filename</span></span></code></pre></div><hr>`,50)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3538471/how-to-compress-files-on-linux-5-ways.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3538471/how-to-compress-files-on-linux-5-ways.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/robsean"},{default:i(()=>[...s[4]||(s[4]=[a("robsean",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const w=l(c,[["render",h]]);export{x as __pageData,w as default};
